You are implementing the Gradle infrastructure for Phase 2 of a KMP (Kotlin Multiplatform) project. This is a book reading leaderboard app.

## Project Root
`/Users/se/git/cc-experiments`

## Current state
- `settings.gradle.kts` includes only `"shared-dto"` and `"backend"`
- `gradle/libs.versions.toml` has only JVM/Spring plugins, Kotlin 2.3.10, kotlinx-serialization 1.10.0
- `build.gradle.kts` (root) has only JVM/Spring plugin aliases
- No `gradle.properties` exists
- `shared-dto/build.gradle.kts` uses `kotlin("jvm")` only — needs to become KMP
- No `client/` module exists yet

## Task: Make ALL the following changes

### 1. `settings.gradle.kts` — Add "client" to include
```kotlin
rootProject.name = "book-leaderboard"
include("shared-dto", "backend", "client")
// ... rest unchanged
```

### 2. `gradle/libs.versions.toml` — Replace entirely with:
```toml
[versions]
agp = "9.0.1"
androidx-activity = "1.12.4"
androidx-datastore = "1.2.0"
build-android-compileSdk = "36"
build-android-minSdk = "26"
build-android-targetSdk = "36"
compose-multiplatform = "1.10.1"
javaVersion = "21"
koin-bom = "4.1.1"
kotlin = "2.3.10"
kotlinx-coroutines = "1.10.2"
kotlinx-serialization = "1.10.0"
ktor = "3.4.0"
ktlint = "1.8.0"
spring-boot = "4.0.2"
spring-dependency-management = "1.1.7"

[libraries]
android-tools-gradle = { module = "com.android.tools.build:gradle", version.ref = "agp" }
androidx-datastore-core-okio = { module = "androidx.datastore:datastore-core-okio", version.ref = "androidx-datastore" }
koin-bom = { module = "io.insert-koin:koin-bom", version.ref = "koin-bom" }
koin-android = { module = "io.insert-koin:koin-android" }
koin-compose = { module = "io.insert-koin:koin-compose" }
koin-core = { module = "io.insert-koin:koin-core" }
kotlinx-coroutines-core = { module = "org.jetbrains.kotlinx:kotlinx-coroutines-core", version.ref = "kotlinx-coroutines" }
kotlinx-coroutines-swing = { module = "org.jetbrains.kotlinx:kotlinx-coroutines-swing", version.ref = "kotlinx-coroutines" }
kotlinx-serialization-json = { module = "org.jetbrains.kotlinx:kotlinx-serialization-json", version.ref = "kotlinx-serialization" }
ktlint-cli = { module = "com.pinterest.ktlint:ktlint-cli", version.ref = "ktlint" }
ktor-client-content-negotiation = { module = "io.ktor:ktor-client-content-negotiation", version.ref = "ktor" }
ktor-client-core = { module = "io.ktor:ktor-client-core", version.ref = "ktor" }
ktor-client-cio = { module = "io.ktor:ktor-client-cio", version.ref = "ktor" }
ktor-client-darwin = { module = "io.ktor:ktor-client-darwin", version.ref = "ktor" }
ktor-client-js = { module = "io.ktor:ktor-client-js", version.ref = "ktor" }
ktor-client-okhttp = { module = "io.ktor:ktor-client-okhttp", version.ref = "ktor" }
ktor-serialization-kotlinx-json = { module = "io.ktor:ktor-serialization-kotlinx-json", version.ref = "ktor" }

[plugins]
android-library = { id = "com.android.kotlin.multiplatform.library", version.ref = "agp" }
kotlin-jvm = { id = "org.jetbrains.kotlin.jvm", version.ref = "kotlin" }
kotlin-multiplatform = { id = "org.jetbrains.kotlin.multiplatform", version.ref = "kotlin" }
kotlin-plugin-jpa = { id = "org.jetbrains.kotlin.plugin.jpa", version.ref = "kotlin" }
