compose-compiler = { id = "org.jetbrains.kotlin.plugin.compose", version.ref = "kotlin" }
compose-multiplatform = { id = "org.jetbrains.compose", version.ref = "compose-multiplatform" }
spring-boot = { id = "org.springframework.boot", version.ref = "spring-boot" }
spring-dependency-management = { id = "io.spring.dependency-management", version.ref = "spring-dependency-management" }
```

### 3. `build.gradle.kts` (root) — Replace entirely with:
```kotlin
plugins {
    alias(libs.plugins.android.library) apply false
    alias(libs.plugins.compose.compiler) apply false
    alias(libs.plugins.compose.multiplatform) apply false
    alias(libs.plugins.kotlin.jvm) apply false
    alias(libs.plugins.kotlin.multiplatform) apply false
    alias(libs.plugins.kotlin.plugin.jpa) apply false
    alias(libs.plugins.kotlin.plugin.serialization) apply false
    alias(libs.plugins.kotlin.plugin.spring) apply false
    alias(libs.plugins.spring.boot) apply false
    alias(libs.plugins.spring.dependency.management) apply false
}

allprojects {
    apply(from = "$rootDir/ktlint.gradle")
}
```

### 4. Create `gradle.properties` (new file):
```properties
org.gradle.jvmargs=-Xmx4G
org.gradle.caching=true
org.gradle.parallel=true

kotlin.daemon.jvmargs=-Xmx4G
kotlin.incremental.wasm=true

android.useAndroidX=true
```

### 5. `shared-dto/build.gradle.kts` — Convert from JVM to KMP:

The source files are already in `src/main/kotlin/com/bookreads/dto/`. Keep them there — just configure `commonMain` to use that srcDir. The backend's `implementation(project(":shared-dto"))` continues to work (gets the JVM artifact).

```kotlin
plugins {
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.kotlin.plugin.serialization)
}

group = "com.bookreads"

kotlin {
    jvmToolchain(libs.versions.javaVersion.get().toInt())

    jvm()
    iosArm64()
    iosSimulatorArm64()
    wasmJs { browser() }

    sourceSets {
        commonMain {
            kotlin.srcDirs("src/main/kotlin")
            dependencies {
                implementation(libs.kotlinx.serialization.json)
            }
        }
    }
}
```

### 6. Create `client/build.gradle.kts` (new file):

```kotlin
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.compose.compiler)
    alias(libs.plugins.compose.multiplatform)
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.kotlin.plugin.serialization)
}

group = "com.bookreads"

kotlin {
    jvmToolchain(libs.versions.javaVersion.get().toInt())

    androidLibrary {
        namespace = "com.bookreads.client"
        compileSdk = libs.versions.buildAndroidCompileSdk.get().toInt()
        minSdk = libs.versions.buildAndroidMinSdk.get().toInt()
    }

    jvm()

    iosArm64()
    iosSimulatorArm64()

    wasmJs { browser() }

    sourceSets {
        commonMain.dependencies {
            implementation(project(":shared-dto"))
            implementation(libs.kotlinx.coroutines.core)
            implementation(libs.kotlinx.serialization.json)
            implementation(libs.ktor.client.core)
            implementation(libs.ktor.client.content.negotiation)
            implementation(libs.ktor.serialization.kotlinx.json)
            implementation(project.dependencies.platform(libs.koin.bom))
            implementation(libs.koin.core)
        }

        androidMain.dependencies {
            implementation(libs.androidx.datastore.core.okio)
            implementation(libs.ktor.client.okhttp)
            implementation(libs.koin.android)
        }

        jvmMain.dependencies {
            implementation(libs.androidx.datastore.core.okio)
            implementation(libs.ktor.client.cio)
            implementation(libs.kotlinx.coroutines.swing)
        }

        iosMain.dependencies {
            implementation(libs.androidx.datastore.core.okio)
            implementation(libs.ktor.client.darwin)
        }

        wasmJsMain.dependencies {
            implementation(libs.ktor.client.js)
        }

        commonTest.dependencies {
            implementation(kotlin("test"))
            implementation(libs.kotlinx.coroutines.core)
        }

        jvmTest.dependencies {
            implementation(kotlin("test-junit5"))
        }
    }
}

tasks.withType<Test> {
    useJUnitPlatform()
}
```

**IMPORTANT notes for the `client/build.gradle.kts`:**
- The version catalog aliases use dots: `libs.versions.buildAndroidCompileSdk` (for `build-android-compileSdk` in toml — Gradle converts hyphens to camelCase in dot notation)
- The `androidLibrary {}` block is inside `kotlin {}` (NOT a top-level `android {}` block) — this is the new-style AGP 9.x multiplatform library plugin
- Do NOT add `android { }` as a top-level block
- The `iosMain` source set is automatically shared between iosArm64 and iosSimulatorArm64

## Execution
Read each file before modifying it. Write all 6 files.

After writing, verify the files are syntactically reasonable by reading them back.

